INSERT INTO "unit_abilities" VALUES(1144002002,1008904,'优势：机动战士高达UC LV4','[{"tid": 100890400, "trait_id": 100890401, "trait": {"id": 100890401, "trait_type": 7, "trait_value": 30, "desc": "发起对战的敌方包含「机动战士高达UC」系列时，\n自身攻击力及防御力提升30%", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000307, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 30, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000307, "trait_condition_set_id": 1000307, "group_id": "キラー_机动戦士ガンダムUC攻撃", "target": "AttackTarget", "unit_tags": "", "unit_role": "", "unit_series": "1250", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": {"id": 1250, "world_id": 1, "name": "机动战士高达UC", "desc": "最初发表于角川书店发行的杂志《GUNDAM ACE》，由福井晴敏先生撰写的小说。\n以剧场版动画《机动战士高达 马沙之反击》3年后的时代为舞台，故事围绕著于宇宙殖民卫星「工业七号」就读阿纳海姆电子工业专科学校的学生巴纳吉‧林克斯展开，自《GUNDAM ACE》2007年2月号起开始连载。\n此外，以本作品为基础，并由SUNRISE企划、制作的OVA《机动战士高达UC》亦于日后公布，从2010年2月20日举办《机动战士高达UC episode1 「独角兽之日」》的上映活动开始，至2014年5月17日的《机动战士高达UC episode7 「彩虹的彼端」》为止，成为全七部的影像作品。", "icon": "series_1250", "sort": 315, "schedule_id": 2509601801, "scenario_stage_series_id": 1250, "scenario": null, "scenarios": null, "scenario_stages": null}, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": null, "character_series": null, "character_tags": null}, "trait_boost": null, "granted_trait_set": null}}]');
