INSERT INTO "unit_abilities" VALUES(1175001200,1017702,'优势：机动战士V高达 LV2','[{"tid": 101770200, "trait_id": 101770201, "trait": {"id": 101770201, "trait_type": 7, "trait_value": 20, "desc": "发起对战的敌方包含「机动战士V高达」系列时，\n自身攻击力及防御力提升20%", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000636, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 10, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000636, "trait_condition_set_id": 1000636, "group_id": "キラー_机动戦士Vガンダム攻撃", "target": "AttackTarget", "unit_tags": "", "unit_role": "", "unit_series": "1750", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": {"id": 1750, "world_id": 1, "name": "机动战士V高达", "desc": "宇宙世纪153年，自人类的生活圈扩大到宇宙以来，已过了一个半世纪，地球圈正陷入世人称为「宇宙战国时代」的混乱期。\n就在这局势中，住在东欧的非法居住区「加沙里尼亚点」的胡索‧艾宾与夏克蒂‧卡林，被卷入侵略地球的殖民卫星国家「渣斯卡路帝国」和抵抗侵略的反抗组织「神圣军事同盟」之间的战斗，迫不得已在战火中越陷越深。一心想保护身边的亲朋好友而成为V高达驾驶员的胡索，在初次造访的宇宙邂逅了住在海兰德的孩子们，同时却也失去许多伙伴。", "icon": "series_1750", "sort": 370, "schedule_id": 0, "scenario_stage_series_id": 1750, "scenario": null, "scenarios": null, "scenario_stages": null}, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": null, "character_series": null, "character_tags": null}, "trait_boost": null, "granted_trait_set": null}}]');
