INSERT INTO "unit_abilities" VALUES(1430008002,1010004,'优势：机动战士高达 铁血孤儿 LV4','[{"tid": 101000400, "trait_id": 101000401, "trait": {"id": 101000401, "trait_type": 7, "trait_value": 30, "desc": "发起对战的敌方包含「机动战士高达 铁血孤儿」系列时，\n自身攻击力及防御力提升30%", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000394, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 30, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000394, "trait_condition_set_id": 1000394, "group_id": "キラー_机动戦士ガンダム 鉄血のオルフェンズ攻撃", "target": "AttackTarget", "unit_tags": "", "unit_role": "", "unit_series": "4300", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": {"id": 4300, "world_id": 0, "name": "机动战士高达 铁血孤儿", "desc": "被称为「厄祭战争」的世纪大战结束后约300年……\n统治结构尽毁的地球圈，借由全新支配体系陆续恢复和平，但相距甚远的火星圈，却刚埋下新的战火引线。\n为了促成火星独立运动而前往地球圈的少女古荻利亚‧蓝那‧伯恩斯坦，担任其护卫的少年兵团三日月‧奥格斯等人，以及力求维持世界和平的强大军事组织加拉尔号角……\n不同立场与想法互相抵触，善变的世界将人玩弄掌心之中，即使如此，少年们仍拚命寻求一线生机。", "icon": "series_4300", "sort": 900, "schedule_id": 0, "scenario_stage_series_id": 4300, "scenario": null, "scenarios": null, "scenario_stages": null}, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "